'use strict';
(() => {
const C=window.TALLADO,G=window.TALLADO_GAME,KEY='ludaria_tallado_mecanicas_v1';
const sealNames=['Relaciones','Bucle','Coherencia'];
const defaults=()=>({version:1,page:0,visited:[0],seals:['pending','pending','pending'],hints:[0,0,0],levels:{},order:[],coherence:null,fields:{},tab:'dynamics',moves:[],timer:{left:600,running:false},recorded:false});
let state=defaults(),storageOK=true,feedback={},opener=null,toastTimer,game=G.empty();
try {
  const s=JSON.parse(localStorage.getItem(KEY)||'null');
  if(s&&s.version===1) {
    state={...state,...s};
    if(!Number.isInteger(state.page)||state.page<0||state.page>=10)state.page=0;
    state.visited=Array.isArray(s.visited)?[...new Set(s.visited.filter(n=>Number.isInteger(n)&&n>=0&&n<10))]:[0];
    state.seals=Array.isArray(s.seals)&&s.seals.length===3?s.seals.map(v=>['solved','assisted'].includes(v)?v:'pending'):defaults().seals;
    state.hints=Array.isArray(s.hints)&&s.hints.length===3?s.hints.map(v=>Number.isInteger(v)?Math.max(0,Math.min(2,v)):0):[0,0,0];
    state.fields={};for(const id of Object.keys(C.fields))if(typeof s.fields?.[id]==='string')state.fields[id]=s.fields[id].slice(0,6000);
    state.levels={};for(let n=0;n<3;n++)if(['d','m','c'].includes(s.levels?.[n]))state.levels[n]=s.levels[n];
    state.order=Array.isArray(s.order)?s.order.filter((v,n,a)=>C.loopSteps.some(x=>x.id===v)&&a.indexOf(v)===n):[];
    state.coherence=[0,1,2].includes(s.coherence)?s.coherence:null;
    if(!['dynamics','mechanics','components'].includes(state.tab))state.tab='dynamics';
    game=G.replay(s.moves);state.moves=game.moves;
    state.timer={left:Number.isFinite(s.timer?.left)?Math.min(600,Math.max(0,Math.floor(s.timer.left))):600,running:false};
    state.recorded=s.recorded===true;
    if(state.seals[0]==='solved'&&!C.levels.every((x,n)=>state.levels[n]===x.answer))state.seals[0]='pending';
    if(state.seals[1]==='solved'&&state.order.join()!==C.loopSteps.map(x=>x.id).join())state.seals[1]='pending';
    if(state.seals[2]==='solved'&&state.coherence!==C.coherence.correct)state.seals[2]='pending';
  }
}catch(e){storageOK=false;}
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}};
const sealStatus=v=>v==='solved'?'Resuelto':v==='assisted'?'Apertura acompañada':'Por resolver';
const btn=(id,label,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${id}" ${attrs}>${label}</button>`;
const tiny=(id,label,attrs='')=>`<button class="text-button" data-action="${id}" ${attrs}>${label}</button>`;
const field=(id,rows=2,scope='page')=>{const f=C.fields[id],domId=`field-${scope}-${id}`;return `<label class="field" for="${domId}">${f.label}${f.short?`<input type="text" id="${domId}" data-field="${id}" maxlength="500" value="${esc(state.fields[id])}" placeholder="${esc(f.placeholder)}">`:`<textarea id="${domId}" data-field="${id}" rows="${rows}" maxlength="6000" placeholder="${esc(f.placeholder)}">${esc(state.fields[id])}</textarea>`}</label>`;};
const count=ids=>ids.filter(id=>state.fields[id]?.trim()).length;
const fb=k=>feedback[k]?`<div class="feedback ${feedback[k].kind||''}" role="status">${feedback[k].text}</div>`:'';
const title=(n,text,desc='')=>`<div class="section-title"><div><span class="eyebrow">${['EL TALLER DE BRYN','EL ENCARGO DE LA MAESTRA','ELEGIR PARA COMPRENDER','LABORATORIO DE JUGADAS','PRIMER UMBRAL','SEGUNDO UMBRAL','EL TALLADO EN PAREJAS','TERCER UMBRAL','CAMARADERÍA EN LA CANTERA','LA SENDA CONTINÚA'][n]}</span><h2>${text}</h2></div><span class="time-label">${C.pages[n].time} min · ${n<2?'en grupo':'en parejas'}</span></div>${desc?`<p class="lead">${desc}</p>`:''}`;
const scene=body=>`<section class="scene"><div class="scene-content wide">${body}</div></section>`;
const sourceLine=(ids,note='')=>`<div class="source-line">${ids.map(id=>tiny('source',C.sources[id].short,`data-source="${id}"`)).join('')}</div>${note?`<p class="note">${note}</p>`:''}`;
const glyph=opened=>`<div class="lock-glyph" aria-hidden="true"><svg viewBox="0 0 48 48"><rect x="10" y="21" width="28" height="22" rx="3"/><path d="${opened?'M17 21v-7a8 8 0 0 1 15-4':'M16 21v-7a8 8 0 0 1 16 0v7'}"/><circle cx="24" cy="30" r="2"/><path d="M24 32v5"/></svg></div>`;
const lockPanel=i=>{const opened=state.seals[i]!=='pending';return `<aside class="lock-panel ${opened?'open':''}">${glyph(opened)}<div class="lock-meta"><span class="eyebrow">CANDADO ${['I','II','III'][i]}</span><h3>${sealNames[i]}</h3></div><p>${opened?sealStatus(state.seals[i]):['Conecta las tres escalas del diseño.','Reconstruye una acción que vuelve a comenzar.','Alinea una regla con el propósito.'][i]}</p>${opened?btn('reward','Consultar la pauta',`data-seal="${i}"`,true):'<span class="note">Desbloquea una pauta complementaria</span>'}</aside>`;};
const lockActions=i=>`<div class="actions">${btn('check','Comprobar el tallado',`data-seal="${i}"`)}${tiny('hint','Pedir una pista',`data-seal="${i}"`)}</div>${fb('lock'+i)}<p class="note">${tiny('assist','Abrir con acompañamiento',`data-seal="${i}"`)} · Las instrucciones y la navegación siguen disponibles.</p>`;
const choice=(i,text,selected)=>`<button class="choice ${selected?'selected':''}" data-action="coherence" data-option="${i}" aria-pressed="${selected}"><span class="choice-mark" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${text}</span></button>`;
const timerText=()=>`${String(Math.floor(state.timer.left/60)).padStart(2,'0')}:${String(state.timer.left%60).padStart(2,'0')}`;
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4300);}
function response(k,text,kind=''){feedback[k]={text,kind};render(false);}
function showModal(titleText,body){
  if(!$('modal').open)opener=document.activeElement;
  $('modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${titleText}</h2>${body}`;
  if(!$('modal').open)$('modal').showModal();
  $('modal-title').focus({preventScroll:true});
}
function closeModal(){if($('modal').open)$('modal').close();}
function gameStatus(){if(game.winner)return `La ficha ${game.winner===1?'A · jade':'B · oro'} ha formado una línea de cuatro. Observemos cómo se llegó a ese estado.`;if(game.draw)return 'Tablero completo sin línea de cuatro: empate. Revisemos las decisiones.';return `Turno de ${game.turn===1?'A · jade':'B · oro'}. Elige una columna disponible.`;}
function boardHTML(){
  const last=game.moves.length?G.play(G.replay(game.moves.slice(0,-1)),game.moves.at(-1)):null;
  return `<div class="board-panel"><div class="board-status" role="status">${gameStatus()}</div><div class="column-buttons">${Array.from({length:7},(_,c)=>`<button class="column-button" data-action="play" data-column="${c}" aria-label="Jugar en columna ${c+1}" ${game.board[0][c]||game.winner||game.draw?'disabled':''}><span>${c+1}</span><span aria-hidden="true">↓</span></button>`).join('')}</div><div class="stone-board" role="img" aria-label="Tablero de seis filas y siete columnas. ${game.board.map((row,r)=>`Fila ${r+1}: ${row.map(v=>v===1?'A':v===2?'B':'vacía').join(', ')}`).join('. ')}">${game.board.flatMap((row,r)=>row.map((v,c)=>`<span class="board-cell ${v?'player-'+v:''} ${game.line.some(([lr,lc])=>lr===r&&lc===c)?'winning':''}" aria-hidden="true">${v?(v===1?'A':'B'):''}</span>`)).join('')}</div><div class="game-legend"><span><i class="jade" aria-hidden="true"></i>A · jade</span><span><i class="gold" aria-hidden="true"></i>B · oro</span><span>${game.moves.length} jugadas</span></div><div class="board-actions">${tiny('undo','Deshacer jugada')}${tiny('board-reset','Vaciar tablero')}${tiny('demo','Ver una amenaza')}</div><p class="move-trace">${last&&!last.error?`Última jugada: ${last.player===1?'A':'B'} colocó en columna ${last.column+1}, fila ${last.row+1}. Cambió el estado y las opciones de la siguiente persona.`:'Haz una jugada. Pregunta qué permite la regla y qué cambia después.'}</p></div>`;
}
const pages=[
()=>`<section class="scene"><div class="cover-content"><span class="eyebrow">CANTERA DE LOS ELEMENTOS · MISIÓN SECUNDARIA 1</span><h1 class="cover-title">El Tallado<br>de <span>Mecánicas</span></h1><p class="lead">Las piezas están a la vista. Su arquitectura, todavía oculta. Desarma un juego, sigue sus acciones y descubre qué lo hace funcionar.</p><div class="actions">${btn('begin','Entrar al taller')}${tiny('map','Explorar el recorrido')}</div><div class="cover-meta"><span class="small-line"></span><span>Maestra Bryn</span><span>Maestría</span></div><p class="note">Sesión 6 · módulo 2 · taller en parejas</p></div><span class="media-note">LUDARIA · CADA REGLA DEJA UNA HUELLA</span></section>`,
()=>scene(`${title(1,'No enumeres las piezas.<br>Explica sus relaciones.')}<div class="mentor">«Una buena talla revela cómo una regla se convierte en una acción, y cómo esa acción transforma la experiencia».<small>MAESTRA BRYN · DIÁLOGO NARRATIVO DE ESTA MISIÓN</small></div><div class="three-column">${[['I','Relaciones','Distingue las tres escalas.'],['II','Bucle','Sigue una decisión y su respuesta.'],['III','Coherencia','Revisa si las reglas apoyan el propósito.']].map(([n,t,d])=>`<div class="panel"><span class="num">${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><p class="note">Trabajen en parejas: una persona describe; la otra pregunta «¿qué regla lo permite?» y «¿dónde lo vemos?». Luego cambien de rol. Pistas y reintentos sin penalización.</p>`),
()=>scene(`${title(2,'La piedra que elegimos','Elijan un juego que ambos conozcan bien. Delimiten una versión y una situación que puedan explicar.')}<div class="split game-choice"><div class="work-grid">${field('game')}${field('team')}${field('goal')}${field('rules')}${field('evidence')}</div><aside class="panel"><span class="eyebrow">OBJETO DE ANÁLISIS</span><h3>Una jugada concreta<br>vale más que una lista.</h3><p>Puede ser de mesa, digital o una experiencia lúdica conocida. Revisen sus reglas y elijan un momento para observar.</p><div class="actions">${btn('use-model','Elegir cuatro en línea','',true)}</div><p class="note">El modelo completa solo los campos vacíos del encargo. Pueden adaptar o cambiar su elección.</p></aside></div><p class="note">Producto: juego delimitado, reglas relevantes y fuente o situación observada. ${storageOK?'Borrador guardado en este navegador.':'Copia tu registro para conservarlo.'}</p>`),
()=>scene(`${title(3,'Bajo la lupa del tallador','Realicen unas jugadas. Deténganse: ¿qué regla permite la acción y qué cambia en el tablero?')}<div class="split microscope"><div>${boardHTML()}</div><div class="lens-area"><span class="eyebrow">MODELO DE ANÁLISIS · CUATRO EN LÍNEA</span><p>Dos personas alternan fichas. Cada ficha cae a la posición libre más baja de su columna. Gana quien forma cuatro en línea horizontal, vertical o diagonal.</p><div class="lens-buttons">${C.lenses.map((l,n)=>`<button class="evidence-card" data-action="lens" data-lens="${l.id}"><small>LENTE ${String(n+1).padStart(2,'0')}</small><strong>${l.title}</strong></button>`).join('')}</div>${sourceLine(['hasbro','wh2012','sicart'],'Demostración en un mismo dispositivo. Regla, acción y estrategia son preguntas diferentes. Las lentes contienen interpretaciones de esta misión.')}<div class="actions">${btn('model-map','Ver la relación completa','',true)}</div></div></div>`),
()=>scene(`${title(4,'Las escalas del diseño','Clasifiquen estas descripciones. ¿Hablan de la experiencia global, del proceso o de una realización específica?')}<div class="split challenge-split"><div>${C.levels.map((x,n)=>`<div class="classification"><span><span class="card-number">${n+1}.</span>${x.text}</span><select data-level="${n}" aria-label="Nivel de la descripción ${n+1}"><option value="">Elegir nivel…</option>${[['d','Dinámicas'],['m','Mecánicas'],['c','Componentes']].map(([v,l])=>`<option value="${v}" ${state.levels[n]===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}${lockActions(0)}${sourceLine(['wh2012'],'El candado revela una pauta de relaciones. El análisis del juego elegido permanece accesible.')}</div>${lockPanel(0)}</div>`),
()=>scene(`${title(5,'Una acción vuelve a comenzar','Ordenen el ciclo desde observar la situación. Pulsen cada paso en el orden que proponen.')}<div class="split challenge-split"><div><ol class="loop-order" aria-label="Orden propuesto">${Array.from({length:5},(_,n)=>{const step=C.loopSteps.find(x=>x.id===state.order[n]);return `<li class="${step?'filled':''}"><span class="num">${n+1}</span><span>${step?step.label:'Paso por elegir'}</span></li>`;}).join('')}</ol><div class="loop-choices">${['response','act','observe','adjust','decide'].map(id=>{const x=C.loopSteps.find(s=>s.id===id);return btn('order-add',x.label,`data-step="${id}" ${state.order.includes(id)?'disabled':''}`,true);}).join('')}</div><div class="board-actions">${tiny('order-undo','Deshacer último paso')}${tiny('order-reset','Reordenar desde el inicio')}</div>${lockActions(1)}<p class="note">Ciclo de observación elaborado para este taller. En otros juegos pueden cambiar el orden, la duración y las personas que responden.</p></div>${lockPanel(1)}</div>`),
()=>{const active=C.lenses.find(l=>l.id===state.tab);const ids=[state.tab,'link','loop'];return scene(`${title(6,'El tallado en parejas','Completen las tres escalas de su juego. Expliquen una relación y describan un ciclo que se repite.')}<div class="worksheet-bar"><span class="pill">${esc(state.fields.game||'Juego por elegir')}</span><span id="worksheet-count" class="note">${count(['dynamics','mechanics','components','link','loop'])}/5 campos con texto</span>${tiny('encargo','Ver el encargo')}</div><div class="worksheet-tabs" role="tablist" aria-label="Escala del análisis">${C.lenses.map(l=>`<button role="tab" id="tab-${l.id}" aria-controls="worksheet-panel" aria-selected="${state.tab===l.id}" tabindex="${state.tab===l.id?0:-1}" data-action="tab" data-tab="${l.id}">${l.id==='components'?'Componentes':l.title}<span aria-hidden="true">${state.fields[l.id]?.trim()?'•':''}</span></button>`).join('')}</div><div class="worksheet" id="worksheet-panel" role="tabpanel" aria-labelledby="tab-${state.tab}"><div class="worksheet-prompt"><strong>${active.tag}</strong><p>${({dynamics:'¿Qué experiencia enmarcan las reglas? Separa lo que observaste de lo que infieres.',mechanics:'Nombra acciones, condiciones y consecuencias. ¿Qué hace quien juega y bajo qué reglas?',components:'Identifica realizaciones concretas y explica qué función cumplen en las acciones del juego.'})[state.tab]}</p></div>${field(state.tab,3)}<div class="work-grid">${field('link',2)}${field('loop',2)}</div></div><div class="actions">${btn('review','Abrir pauta de revisión','',true)}${tiny('notebook','Ver todos mis campos')}</div><p class="note">Producto: plantilla de los tres niveles, relación justificada y bucle. Tener texto en los campos registra el borrador; su calidad se revisa conversando.</p>`);},
()=>scene(`${title(7,'Cuando la regla desvía el propósito','Caso ficticio: lee el encargo y decide qué ajuste da coherencia al sistema.')}<div class="split challenge-split"><div><div class="case-panel"><p class="case-summary">${C.coherence.case}</p></div><h3 class="question-title">${C.coherence.question}</h3><div class="options">${C.coherence.options.map((o,n)=>choice(n,o.text,state.coherence===n)).join('')}</div>${lockActions(2)}<div class="actions">${tiny('coherence-notes','Registrar una tensión de nuestro juego')}</div>${sourceLine(['wh2015'],'El caso y las opciones son propios. Un ajuste coherente es una hipótesis de diseño que conviene observar.')}</div>${lockPanel(2)}</div>`),
()=>scene(`${title(8,'El intercambio de tallados','Compartan su lectura con otra pareja. Una pregunta precisa puede revelar una relación que pasó inadvertida.')}<div class="split peer-split"><div><div class="steps">${[['01','Presenten','Una regla, la acción que permite y una evidencia.'],['02','Pregunten','¿Qué comportamiento invita? ¿Qué otra lectura sería posible?'],['03','Ajusten','Revisen una relación y registren qué cambió.']].map(([n,t,d])=>`<div class="step"><span class="num">${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div><div class="work-grid peer-fields">${field('shared')}${field('peer')}</div></div><aside class="timer-box"><span class="eyebrow">TIEMPO DE CONVERSACIÓN</span><div class="timer" id="timer">${timerText()}</div><div class="actions">${btn('timer-toggle',state.timer.running?'Pausar':'Iniciar','',true)}${tiny('timer-reset','Reiniciar')}</div><p class="note">4 minutos por pareja y 2 para ajustar. Temporizador opcional: pueden seguir al terminar.</p><div class="header-rule"></div><p class="note">Tras el intercambio, el facilitador entrega el código real por colaboración en el sistema del proyecto.</p></aside></div>`),
()=>scene(`${title(9,'La huella que conservamos','Ahora puedes explicar cómo una regla se convierte en una acción y cómo esa acción se relaciona con la experiencia.')}<div class="final-seals">${sealNames.map((name,n)=>`<div class="final-seal ${state.seals[n]}"><strong>${name}</strong><small>${sealStatus(state.seals[n])}</small></div>`).join('')}</div><div class="work-grid">${field('exit')}${field('transfer')}</div><div class="actions">${btn('finish','Guardar mi cierre')}${btn('record','Ver y descargar mi registro','',true)}${tiny('async','Trabajo autónomo · 45 min')}</div>${state.recorded?'<p class="note"><span class="pill">Reflexión guardada</span> Compártela por el canal de tu clase y llévala a la bitácora del buscador.</p>':''}<div class="header-rule"></div><p class="note">Próximo encuentro: <strong>La Gema Motivacional</strong>. Allí cerraremos el módulo 2 y recuperaremos el segundo fragmento del Orbe.</p>`)
];
function render(focus=true){
  const a=document.activeElement;
  const focusAttrs=a?.dataset?.action?{...a.dataset}:null;
  $('stage').innerHTML=pages[state.page]();
  document.body.classList.toggle('is-cover',state.page===0);
  $('page-count').textContent=`${String(state.page+1).padStart(2,'0')} / 10`;
  $('previous').disabled=state.page===0;
  $('next-label').textContent=state.page===9?'Mi registro':'Siguiente';
  $('route-dots').innerHTML=C.pages.map((p,n)=>`<button class="route-dot ${state.visited.includes(n)?'visited':''} ${state.page===n?'current':''}" data-action="go" data-page="${n}" aria-label="Pantalla ${n+1}: ${p.title}" ${state.page===n?'aria-current="step"':''}></button>`).join('');
  $('seal-status').innerHTML=sealNames.map((name,n)=>`<button class="seal-dot ${state.seals[n]}" data-action="seal" data-seal="${n}" aria-label="Candado de ${name}: ${sealStatus(state.seals[n])}">${['I','II','III'][n]}</button>`).join('');
  if(focus)$('stage').focus({preventScroll:true});
  else if(focusAttrs){const candidate=[...$('stage').querySelectorAll('[data-action]')].find(el=>Object.entries(focusAttrs).every(([k,v])=>el.dataset[k]===v));candidate&&!candidate.disabled&&candidate.focus({preventScroll:true});}
}
function go(n){
  if(!Number.isInteger(n)||n<0||n>=10)return;
  closeModal();if(n!==8)state.timer.running=false;
  state.page=n;if(!state.visited.includes(n))state.visited.push(n);save();
  const hash='#pantalla-'+(n+1);if(location.hash!==hash)history.replaceState(null,'',hash);
  render();window.scrollTo({top:0,behavior:'instant'});
}
function reward(n){
  if(![0,1,2].includes(n))return;
  if(state.seals[n]==='pending'){go([4,5,7][n]);return;}
  const r=C.rewards[n];showModal(r.title,`<span class="pill">${sealStatus(state.seals[n])}</span><ul class="reward-list">${r.items.map(x=>`<li>${x}</li>`).join('')}</ul><p class="note">Pauta complementaria para acompañar el análisis. Revisa el producto con tu pareja y el facilitador.</p>`);
}
function unlock(n,kind='solved'){state.seals[n]=kind;delete feedback['lock'+n];save();render(false);reward(n);}
function check(n){
  if(n===0){const ready=C.levels.every((_,i)=>state.levels[i]);if(!ready){response('lock0','Elige un nivel para cada descripción. Puedes pedir una pista o revisar el modelo.','hint');return;}const right=C.levels.every((x,i)=>state.levels[i]===x.answer);if(right){unlock(0);return;}response('lock0',C.levels.filter((x,i)=>state.levels[i]!==x.answer).map(x=>x.why).join(' ')+' Revisa esas relaciones y vuelve a probar.','error');}
  if(n===1){if(state.order.join()===C.loopSteps.map(x=>x.id).join()){unlock(1);return;}response('lock1',state.order.length<5?'Completa los cinco pasos antes de comparar. Parte de observar la situación actual.':'En este ciclo, observar precede a elegir; ejecutar la acción cambia el estado y ofrece información. Esa respuesta permite ajustar. Reordena y vuelve a probar.','error');}
  if(n===2){if(state.coherence===null){response('lock2','Selecciona una propuesta para contrastarla con el propósito cooperativo.','hint');return;}if(state.coherence===C.coherence.correct){unlock(2);return;}response('lock2',C.coherence.options[state.coherence].why+' Puedes revisar tu elección.','error');}
}
function hint(n){if(![0,1,2].includes(n))return;state.hints[n]=Math.min(2,state.hints[n]+1);save();const texts=[['Piensa en tres escalas: experiencia global, proceso de interacción y realización concreta.','Las relaciones y restricciones enmarcan; los turnos organizan acciones; una insignia representa un logro específico.'],['Parte de la situación que tienes delante y termina usando información para volver a decidir.','Después de observar, decide y actúa. Luego lee qué cambió y ajusta tu próxima decisión.'],['Compara lo que pide el encargo con lo que reconoce la regla.','Si el propósito es construir juntos, revisa una regla que reconozca una decisión conjunta y su explicación.']];response('lock'+n,`<strong>Pista ${state.hints[n]}.</strong> ${texts[n][state.hints[n]-1]}`,'hint');}
function source(id){const s=C.sources[id];if(!s)return;showModal(s.short,`<p>${esc(s.apa)}</p><h3>Uso en esta misión</h3><p>${esc(s.use)}</p><h3>Alcance</h3><p>${esc(s.limit)}</p>${s.url?`<div class="actions"><a class="button secondary" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.link}</a></div>`:''}`);}
function sources(){showModal('Las fuentes del tallado',`<p>El alcance parte de la ficha de la tesis. Las explicaciones, el ciclo, los casos y la interfaz son elaboraciones didácticas para esta misión.</p>${Object.entries(C.sources).map(([id,s])=>`<h3>${s.short}</h3><p>${esc(s.apa)}</p><p class="note">${esc(s.use)}</p>${tiny('source','Referencia y alcance',`data-source="${id}"`)}`).join('')}<p class="note">Ilustración original creada con generación de imágenes para Ludaria. Esquemas y tablero realizados con código; sin imágenes ni marcas del juego comercial.</p>`);}
function encargo(){showModal('Nuestro juego y sus reglas',`<div class="work-grid">${['game','team','goal','rules','evidence'].map(id=>field(id,2,'brief')).join('')}</div><p class="note">Acoten una versión y una jugada. Si una regla procede del recuerdo, indiquen qué necesitan verificar.</p>`);}
function notebook(){showModal('La bitácora del tallador',`<p>Conserva la deconstrucción y la revisión recibida. Este registro queda en tu dispositivo; compártelo por el canal indicado en clase.</p><div class="work-grid">${Object.keys(C.fields).map(id=>field(id,2,'book')).join('')}</div><div class="actions">${btn('record','Ver y descargar mi registro')}${btn('review','Pauta de revisión','',true)}</div><p class="note">${storageOK?'Borrador guardado en este navegador.':'El almacenamiento está restringido. Copia el registro para conservarlo.'}</p>`);}
function review(){showModal('Revisar el tallado',`<ul class="reward-list"><li>¿Delimitamos el juego, la versión y la meta?</li><li>¿Distinguimos las tres escalas y justificamos sus relaciones?</li><li>¿Describimos una acción bajo una regla y su consecuencia?</li><li>¿El bucle explica qué información cambia la próxima decisión?</li><li>¿Separamos lo observado de nuestra interpretación?</li><li>¿La pregunta de otra pareja produjo una precisión o un ajuste?</li></ul><p class="note">Pauta para conversación y revisión humana. Las respuestas abiertas no se califican automáticamente.</p>`);}
function exportText(){return ['BUSCADORES DE LA GAMIFICACIÓN PERDIDA','El Tallado de Mecánicas · Sesión 6 · Misión secundaria 1 · Módulo 2','Fecha: '+new Date().toLocaleDateString('es-CL'),'','DECONSTRUCCIÓN EN PAREJAS',...Object.entries(C.fields).flatMap(([id,f])=>[f.label.toUpperCase(),state.fields[id]||'(Sin registro)','']),'PRÁCTICA FORMATIVA LOCAL',...sealNames.map((name,n)=>`${name}: ${sealStatus(state.seals[n])} · pistas consultadas: ${state.hints[n]}`),'','Clasificación de las descripciones',...C.levels.map((x,n)=>`${n+1}. ${x.text} → ${({d:'Dinámicas',m:'Mecánicas',c:'Componentes'})[state.levels[n]]||'Sin elegir'}`),'','Bucle propuesto: '+(state.order.map(id=>C.loopSteps.find(x=>x.id===id).label).join(' → ')||'Sin ordenar'),'Caso de coherencia: '+(C.coherence.options[state.coherence]?.text||'Sin elegir'),'','Los sellos registran práctica local. La valoración del análisis y los códigos reales corresponden al facilitador.','No se envió este registro desde la presentación. Trasládalo a tu bitácora y al canal de clase.','','FUENTES',...Object.values(C.sources).flatMap(s=>[s.apa,s.url||'Fuente proporcionada por el autor',''])].join('\n');}
function record(){showModal('Tu registro del tallado',`<p>Selecciona y copia el texto o solicita su descarga para conservar la deconstrucción.</p><label class="field" for="export-text">Registro completo<textarea id="export-text" readonly rows="10">${esc(exportText())}</textarea></label><div class="actions">${btn('copy','Copiar registro')}${btn('download','Descargar TXT','',true)}</div><p class="note">Si el marco restringe una acción, selecciona el texto y cópialo, o abre la misión en una pestaña.</p>`);}
async function copy(){const el=$('export-text');try{if(!navigator.clipboard?.writeText)throw Error('clipboard');await Promise.race([navigator.clipboard.writeText(exportText()),new Promise((_,reject)=>setTimeout(()=>reject(Error('timeout')),3500))]);toast('Copia solicitada. Puedes seleccionar el texto si lo necesitas.');}catch(e){el?.focus();el?.select();toast('Selecciona el registro y usa la opción Copiar de tu dispositivo.');}}
function download(){const url=URL.createObjectURL(new Blob(['\ufeff'+exportText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Bitacora_El_Tallado_de_Mecanicas.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Descarga solicitada. También tienes el registro visible para copiarlo.');}
function guide(){showModal('Acompañar El Tallado de Mecánicas',`<p>Sesión 6 · misión secundaria 1 · módulo 2 · Cantera de los Elementos · Maestra Bryn · Maestría.</p><p><strong>Objetivo:</strong> deconstruir un juego conocido para revelar su arquitectura interna. Trabajo en parejas: reglas, acciones, comportamientos, bucles y coherencia.</p><ol class="complete-list">${C.pages.map(p=>`<li><strong>${p.title} · ${p.time} min.</strong> ${p.prompt}<br>Producto: ${p.product}</li>`).join('')}</ol><p>Total: 90 minutos sincrónicos + 45 autónomos. Distribución de pantallas propuesta para esta clase.</p><p>Los candados solo abren pautas complementarias. Recoge evidencia de aprendizaje mediante conversación y registros compartidos. Entrega los códigos reales por colaboración en los recursos del proyecto.</p><div class="actions">${btn('async','Preparar el trabajo autónomo','',true)}${tiny('review','Pauta de revisión')}</div><p class="note">Esta presentación guarda borradores por dispositivo. No agrega respuestas de la clase ni actualiza la Forja o el Libro de Stats. El Fragmento II corresponde a La Gema Motivacional.</p>`);}
function handle(name,el){const n=Number(el.dataset.seal);switch(name){
  case 'begin':go(1);break;
  case 'go':go(Number(el.dataset.page));break;
  case 'close':closeModal();break;
  case 'map':showModal('Los pasos del tallado',`<p>Explora cualquier pantalla. Recorrido local: ${state.visited.length}/10 pantallas visitadas.</p><div class="modal-grid">${C.pages.map((p,i)=>`<button class="map-item ${state.page===i?'current':''}" data-action="go" data-page="${i}"><span>${String(i+1).padStart(2,'0')}</span>${p.title}</button>`).join('')}</div><div class="actions">${tiny('guide','Guía docente')}${tiny('sources','Fuentes')}${tiny('reset-ask','Reiniciar esta misión')}</div>`);break;
  case 'guide':guide();break;
  case 'sources':sources();break;
  case 'source':source(el.dataset.source);break;
  case 'lens':{const l=C.lenses.find(x=>x.id===el.dataset.lens);if(l)showModal(l.title,`<span class="eyebrow">${l.tag}</span><p>${l.body}</p><div class="case-panel" style="margin-top:20px"><p>${l.example}</p></div><p class="note">${l.limit}</p>${sourceLine(['wh2012','sicart'])}`);break;}
  case 'model-map':showModal('Una relación que podemos explicar',`<div class="relationship"><div><small>REGLA</small><p>Una ficha por turno en una columna disponible.</p></div><div><small>ACCIÓN</small><p>Elegir dónde colocar para avanzar una línea o bloquear.</p></div><div><small>ESTADO</small><p>El tablero cambia y muestra nuevas posibilidades.</p></div><div><small>EXPERIENCIA POSIBLE</small><p>Anticipar lo que hará la otra persona y revisar la próxima elección.</p></div></div><p class="note">Lectura didáctica propia: la estrategia y la experiencia pueden variar. Compruébenlas con jugadas y con quienes juegan.</p>${sourceLine(['hasbro','sicart','wh2012'])}`);break;
  case 'play':{const r=G.play(game,Number(el.dataset.column));if(r.error){toast(r.error);return;}game=r.state;state.moves=game.moves;save();render(false);const c=document.querySelector(`[data-action="play"][data-column="${el.dataset.column}"]:not(:disabled)`);if(c)c.focus({preventScroll:true});else (document.querySelector('[data-action="play"]:not(:disabled)')||document.querySelector('[data-action="undo"]'))?.focus({preventScroll:true});break;}
  case 'undo':game=G.replay(game.moves.slice(0,-1));state.moves=game.moves;save();render(false);break;
  case 'board-reset':game=G.empty();state.moves=[];save();render(false);toast('Tablero vacío. Pueden observar otra secuencia.');break;
  case 'demo':game=G.replay([0,1,0,1,0,2]);state.moves=game.moves;save();render(false);toast('A tiene tres fichas verticales. ¿Qué elección permite la regla y con qué consecuencia?');break;
  case 'use-model':{const example={game:'Cuatro en línea · reglas clásicas',goal:'Formar una línea de cuatro fichas propias.',rules:'Dos participantes alternan turnos. Se coloca una ficha en una columna disponible; ocupa el espacio libre más bajo. Gana una línea de cuatro en horizontal, vertical o diagonal.',evidence:'Instrucciones de Connect 4 (A5640), Hasbro: https://instructions.hasbro.com/en-us/instruction/Connect-4-Game . Jugadas observadas en la demostración de esta misión.'};for(const [id,value] of Object.entries(example))if(!state.fields[id]?.trim())state.fields[id]=value;save();render(false);toast('Modelo agregado en los campos vacíos. Revísenlo antes de analizar.');break;}
  case 'check':check(n);break;
  case 'hint':hint(n);break;
  case 'reward':case 'seal':reward(n);break;
  case 'assist':showModal('Una apertura acompañada',`<p>Conversa la práctica con el facilitador. Puedes consultar la pauta con apoyo; el sello quedará como «Apertura acompañada».</p><div class="actions">${btn('assist-confirm','Abrir la pauta con apoyo',`data-seal="${n}"`)}${btn('close','Volver a intentar','',true)}</div>`);break;
  case 'assist-confirm':if([0,1,2].includes(n))unlock(n,'assisted');break;
  case 'order-add':if(C.loopSteps.some(x=>x.id===el.dataset.step)&&!state.order.includes(el.dataset.step)){state.order.push(el.dataset.step);state.seals[1]='pending';delete feedback.lock1;save();render(false);(document.querySelector('[data-action="order-add"]:not(:disabled)')||document.querySelector('[data-action="check"][data-seal="1"]'))?.focus({preventScroll:true});}break;
  case 'order-undo':state.order.pop();state.seals[1]='pending';delete feedback.lock1;save();render(false);break;
  case 'order-reset':state.order=[];state.seals[1]='pending';delete feedback.lock1;save();render(false);break;
  case 'coherence':state.coherence=Number(el.dataset.option);state.seals[2]='pending';delete feedback.lock2;save();render(false);break;
  case 'tab':state.tab=el.dataset.tab;save();render(false);break;
  case 'encargo':encargo();break;
  case 'coherence-notes':showModal('Una tensión en nuestro juego',`${field('tension',3)}${field('change',3)}<p class="note">Describe qué cambiarías y qué observarías para revisar el ajuste.</p>`);break;
  case 'review':review();break;
  case 'notebook':notebook();break;
  case 'record':record();break;
  case 'copy':copy();break;
  case 'download':download();break;
  case 'finish':state.recorded=true;save();render(false);toast('Reflexión guardada en este dispositivo. Prepara el registro para compartirlo.');break;
  case 'async':showModal('Afina el tallado · 45 minutos autónomos',`<p>Profundiza la deconstrucción y conserva la versión revisada en tu bitácora.</p><ul class="reward-list"><li><strong>20 min:</strong> verifica reglas y añade una jugada que sostenga la relación entre niveles.</li><li><strong>15 min:</strong> incorpora la pregunta de la otra pareja y afina el bucle o una tensión del sistema.</li><li><strong>10 min:</strong> sintetiza y comparte el registro por el canal indicado en clase.</li></ul><p class="note">La tesis contempla 45 minutos autónomos. Esta distribución es una propuesta de trabajo para el taller.</p><div class="actions">${btn('record','Preparar mi registro','',true)}</div>`);break;
  case 'timer-toggle':state.timer.running=!state.timer.running;if(state.timer.left===0&&state.timer.running)state.timer.left=600;save();render(false);break;
  case 'timer-reset':state.timer={left:600,running:false};save();render(false);break;
  case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Abre la misión en una pestaña para usar pantalla completa.'));break;
  case 'reset-ask':showModal('Reiniciar El Tallado de Mecánicas',`<p>Se borrará el borrador de esta misión en este dispositivo. Conserva primero el registro si lo necesitas.</p><div class="actions">${btn('reset','Reiniciar esta misión')}${btn('record','Ver mi registro antes','',true)}</div>`);break;
  case 'reset':state=defaults();game=G.empty();feedback={};save();go(0);toast('Esta misión vuelve a comenzar.');break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)handle(el.dataset.action,el);});
document.addEventListener('input',e=>{const id=e.target.dataset.field;if(C.fields[id]){state.fields[id]=e.target.value;state.recorded=false;save();if($('worksheet-count'))$('worksheet-count').textContent=`${count(['dynamics','mechanics','components','link','loop'])}/5 campos con texto`;}});
document.addEventListener('change',e=>{const n=Number(e.target.dataset.level);if(e.target.hasAttribute('data-level')&&[0,1,2].includes(n)){state.levels[n]=e.target.value;state.seals[0]='pending';delete feedback.lock0;save();render(false);document.querySelector(`[data-level="${n}"]`)?.focus({preventScroll:true});}});
$('previous').addEventListener('click',()=>go(state.page-1));$('next').addEventListener('click',()=>state.page===9?record():go(state.page+1));
$('modal').addEventListener('close',()=>{const target=opener,attrs=target?.dataset?{...target.dataset}:null;render(false);if(target?.isConnected)target.focus({preventScroll:true});else if(attrs){const next=[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(attrs).every(([k,v])=>el.dataset[k]===v));next?.focus({preventScroll:true});}});
document.addEventListener('keydown',e=>{
  if(e.ctrlKey||e.metaKey||e.altKey||$('modal').open)return;
  const tab=e.target.closest('[role="tab"]');
  if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ids=['dynamics','mechanics','components'];let i=ids.indexOf(state.tab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;state.tab=ids[i];save();render(false);$('tab-'+state.tab).focus();return;}
  if(e.target.closest('input,textarea,select,button,a'))return;
  if(e.key==='ArrowRight'&&state.page<9){e.preventDefault();go(state.page+1);}
  if(e.key==='ArrowLeft'&&state.page>0){e.preventDefault();go(state.page-1);}
});
window.addEventListener('hashchange',()=>{const match=/^#pantalla-(\d+)$/.exec(location.hash);if(match){const n=Number(match[1])-1;if(n>=0&&n<10&&n!==state.page)go(n);}});
setInterval(()=>{if(state.timer.running&&state.page===8){state.timer.left=Math.max(0,state.timer.left-1);if(state.timer.left===0){state.timer.running=false;render(false);toast('Terminó el tiempo orientativo. Pueden seguir conversando.');}else if($('timer'))$('timer').textContent=timerText();save();}},1000);
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)$('fireflies').innerHTML=Array.from({length:12},(_,n)=>`<i class="fly" style="left:${(n*37+9)%100}%;top:${(n*19+13)%100}%;animation-delay:-${n}s"></i>`).join('');
const start=/^#pantalla-(\d+)$/.exec(location.hash);if(start&&Number(start[1])>=1&&Number(start[1])<=10)state.page=Number(start[1])-1;
if(!state.visited.includes(state.page))state.visited.push(state.page);save();render(false);
})();
